@layer components {
  .ew-chip {
    /* anatomy: root */
  }
  .ew-chip {
    display: inline-flex; align-items: center; gap: 6px; max-width: 100%; min-width: 0;
    min-height: 32px; padding: 4px 10px; border-radius: 999px;
    border: 1px solid var(--ew-color-border-strong); background: var(--ew-color-bg-surface);
    color: var(--ew-color-fg-default); font: inherit; cursor: pointer;
  }
  .ew-chip[aria-pressed="true"] { font-weight: 700; box-shadow: inset 0 -2px 0 var(--ew-color-action-bg); }
  .ew-chip__remove { border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; padding: 0 2px; }
  .ew-chip:disabled, .ew-chip[aria-disabled="true"] { opacity: 0.55; cursor: not-allowed; }
  /* spec variant variant=default */
  .ew-chip[data-variant="default"] { --ew-spec-variant-variant: default; }
  .ew-chip:not([data-variant]) { --ew-spec-variant-variant: default; }
  .ew-chip[data-size="sm"] { --ew-spec-size: sm; }
  .ew-chip[data-size="md"] { --ew-spec-size: md; }
  .ew-chip:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-chip, .ew-chip *, .ew-chip *::before, .ew-chip *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
